// ─── File: SagaRollbackDemo.java ───
// Runnable demo: orchestrated Saga rollback via reverse-order idempotent compensations.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SagaRollbackDemo {

    private static final Logger log = Logger.getLogger("sagarollback");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        InventoryService inventory = new InventoryService();
        PaymentService payment = new PaymentService();
        ShipmentService shipment = new ShipmentService(/*fail*/ true);
        OrderSagaOrchestrator saga = new OrderSagaOrchestrator(inventory, payment, shipment, 3);

        // Shipment fails AFTER payment is charged → orchestrator refunds + releases + cancels.
        saga.run("ORD-900", "SAV2001", "BOOK-1", 2, new BigDecimal("50000"));
    }
}

// ─── model/SagaRecord.java ───
class SagaRecord {
    final String sagaId; final String orderId; String state = "RUNNING";
    final Deque<CompensationStep> owed = new ArrayDeque<>();   // LIFO → reverse order
    SagaRecord(String sagaId, String orderId) { this.sagaId = sagaId; this.orderId = orderId; }
}

// ─── orchestrator/CompensationStep.java ───
class CompensationStep {
    final String action; final Runnable undo;
    CompensationStep(String action, Runnable undo) { this.action = action; this.undo = undo; }
}

// ─── service/InventoryService.java — forward + idempotent compensation ───
class InventoryService {
    private static final Logger log = Logger.getLogger("sagarollback");
    private final Set<String> released = new HashSet<>();
    void reserve(String orderId, int qty) { log.info(() -> "[INVENTORY] reserved " + qty + " for " + orderId); }
    void release(String orderId, int qty) {                       // compensation (idempotent)
        if (!released.add(orderId)) { log.fine(() -> "[INVENTORY] release already done for " + orderId); return; }
        log.warning(() -> "[INVENTORY] COMPENSATE released " + qty + " for " + orderId);
    }
}

// ─── service/PaymentService.java — forward + idempotent refund ───
class PaymentService {
    private static final Logger log = Logger.getLogger("sagarollback");
    private final Set<String> refunded = new HashSet<>();
    void charge(String orderId, BigDecimal amount) { log.info(() -> "[PAYMENT] charged " + orderId + " Rs." + amount); }
    void refund(String orderId, BigDecimal amount) {              // compensation (idempotent)
        if (!refunded.add(orderId)) { log.fine(() -> "[PAYMENT] refund already done for " + orderId); return; }
        log.warning(() -> "[PAYMENT] COMPENSATE refunded " + orderId + " Rs." + amount);
    }
}

// ─── service/ShipmentService.java — the failing step + a flaky cancel ───
class ShipmentService {
    private static final Logger log = Logger.getLogger("sagarollback");
    private final boolean fail; private int cancelAttempts = 0;
    ShipmentService(boolean fail) { this.fail = fail; }
    void schedule(String orderId) {
        if (fail) { log.severe(() -> "[SHIPMENT] FAILED to schedule " + orderId); throw new RuntimeException("no courier"); }
        log.info(() -> "[SHIPMENT] scheduled " + orderId);
    }
    // cancel-order compensation that fails ONCE to demonstrate retry.
    void cancelOrder(String orderId) {
        cancelAttempts++;
        if (cancelAttempts == 1) { log.warning(() -> "[ORDER] cancel transient failure (will retry)"); throw new RuntimeException("transient"); }
        log.warning(() -> "[ORDER] COMPENSATE cancelled " + orderId + " (attempt " + cancelAttempts + ")");
    }
}

// ─── orchestrator/OrderSagaOrchestrator.java ───
class OrderSagaOrchestrator {
    private static final Logger log = Logger.getLogger("sagarollback");
    private final InventoryService inventory; private final PaymentService payment; private final ShipmentService shipment;
    private final int maxRetries;
    OrderSagaOrchestrator(InventoryService i, PaymentService p, ShipmentService s, int maxRetries) {
        inventory = i; payment = p; shipment = s; this.maxRetries = maxRetries;
    }

    void run(String orderId, String account, String sku, int qty, BigDecimal amount) {
        SagaRecord saga = new SagaRecord("SAGA-" + orderId, orderId);
        try {
            // T1 reserve → record compensation C1
            inventory.reserve(orderId, qty);
            saga.owed.push(new CompensationStep("RELEASE_STOCK", () -> inventory.release(orderId, qty)));
            // T2 charge → record compensation C2
            payment.charge(orderId, amount);
            saga.owed.push(new CompensationStep("REFUND_PAYMENT", () -> payment.refund(orderId, amount)));
            // Also owe a cancel-order compensation.
            saga.owed.push(new CompensationStep("CANCEL_ORDER", () -> shipment.cancelOrder(orderId)));
            // T3 shipment → FAILS here
            shipment.schedule(orderId);
            saga.state = "COMPLETED";
            log.info(() -> "[SAGA] " + orderId + " COMPLETED");
        } catch (RuntimeException ex) {
            saga.state = "COMPENSATING";
            log.severe(() -> "[SAGA] forward step failed → ROLLBACK via compensations in reverse order");
            rollback(saga);
            saga.state = "CANCELLED";
            log.warning(() -> "[SAGA] " + orderId + " CANCELLED (money refunded, stock released)");
        }
    }

    // Run compensations LIFO (reverse order), each retried and idempotent.
    private void rollback(SagaRecord saga) {
        while (!saga.owed.isEmpty()) {
            CompensationStep step = saga.owed.pop();
            boolean done = false;
            for (int attempt = 1; attempt <= maxRetries && !done; attempt++) {
                try { step.undo.run(); done = true; }
                catch (RuntimeException e) {
                    int a = attempt;
                    log.warning(() -> "[SAGA] compensation " + step.action + " attempt " + a + " failed, retrying");
                }
            }
            if (!done) log.severe(() -> "[SAGA] compensation " + step.action + " EXHAUSTED retries → alert on-call");
        }
    }
}

